<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Vouchers';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';try{if($action==='save'){$id=(int)($_POST['coupon_id']??0);$code=strtoupper(trim($_POST['code']??''));$type=$_POST['discount_type']==='FIXED'?'FIXED':'PERCENT';$value=max(0,(float)$_POST['discount_value']);$minimum=max(0,(float)$_POST['minimum_order']);$expires=trim($_POST['expires_at']??'')?:null;$status=$_POST['status']==='INACTIVE'?'INACTIVE':'ACTIVE';if($id)$pdo->prepare('UPDATE coupons SET code=?,discount_type=?,discount_value=?,minimum_order=?,expires_at=?,status=? WHERE coupon_id=?')->execute([$code,$type,$value,$minimum,$expires,$status,$id]);else$pdo->prepare('INSERT INTO coupons(code,discount_type,discount_value,minimum_order,expires_at,status) VALUES(?,?,?,?,?,?)')->execute([$code,$type,$value,$minimum,$expires,$status]);$msg='Voucher saved.';}elseif($action==='delete'){$pdo->prepare('DELETE FROM coupons WHERE coupon_id=?')->execute([(int)$_POST['coupon_id']]);$msg='Voucher removed.';}}catch(Throwable $e){$err='Could not save this voucher. Make sure the code is unique.';}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM coupons WHERE coupon_id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM coupons ORDER BY coupon_id DESC')->fetchAll();require __DIR__.'/../includes/header.php';?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/products.php">Products</a><a href="/admin/orders.php">Orders</a><a href="/admin/customers.php">Customers</a><a href="/admin/reviews.php">Reviews</a><a class="active" href="/admin/vouchers.php">Vouchers</a><?php if(super_admin()): ?><a href="/admin/users.php">Admin accounts</a><?php endif; ?><a href="/">View store</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">PROMOTIONS</span><h1>Vouchers</h1><p>Create discounts that customers can see and use at checkout.</p></div></div><?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?><?php if($err): ?><div class="errors"><?=e($err)?></div><?php endif; ?><section class="panel"><h2><?= $edit?'Edit voucher':'Create voucher' ?></h2><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="coupon_id" value="<?=$edit['coupon_id']??0?>"><div class="four"><label>Code<input name="code" required value="<?=e($edit['code']??'')?>" placeholder="WELCOME10"></label><label>Type<select name="discount_type"><option <?=($edit['discount_type']??'PERCENT')==='PERCENT'?'selected':''?>>PERCENT</option><option <?=($edit['discount_type']??'')==='FIXED'?'selected':''?>>FIXED</option></select></label><label>Discount value<input type="number" step="0.01" min="0" name="discount_value" value="<?=e((string)($edit['discount_value']??0))?>"></label><label>Minimum order<input type="number" step="0.01" min="0" name="minimum_order" value="<?=e((string)($edit['minimum_order']??0))?>"></label></div><div class="two"><label>Expires at<input type="datetime-local" name="expires_at" value="<?=!empty($edit['expires_at'])?e(date('Y-m-d\TH:i',strtotime($edit['expires_at']))):''?>"></label><label>Status<select name="status"><option <?=($edit['status']??'ACTIVE')==='ACTIVE'?'selected':''?>>ACTIVE</option><option <?=($edit['status']??'')==='INACTIVE'?'selected':''?>>INACTIVE</option></select></label></div><div><button class="btn primary">Save voucher</button><?php if($edit): ?> <a class="btn ghost" href="/admin/vouchers.php">Cancel</a><?php endif; ?></div></form></section><div class="table-wrap"><table><thead><tr><th>Code</th><th>Discount</th><th>Minimum</th><th>Expiry</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $v): ?><tr><td><strong><?=e($v['code'])?></strong></td><td><?=e($v['discount_type'])==='PERCENT'?e($v['discount_value']).'%':'KES '.number_format((float)$v['discount_value'],2)?></td><td><?=money((float)$v['minimum_order'])?></td><td><?=e($v['expires_at']??'No expiry')?></td><td><?=e($v['status'])?></td><td><a class="btn small" href="/admin/vouchers.php?edit=<?=$v['coupon_id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Remove this voucher?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="coupon_id" value="<?=$v['coupon_id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php'; ?>
